'use strict';

// MODULES //

import isnan from '@stdlib/math-base-assert-is-nan';
import sqrt from '@stdlib/math-base-special-sqrt';
import exp from '@stdlib/math-base-special-exp';


// MAIN //

/**
* Evaluates the moment-generating function (MGF) for a Wald distribution with mean `mu` and shape parameter `lambda` at a value `t`.
*
* @param {number} t - input value
* @param {PositiveNumber} mu - mean
* @param {PositiveNumber} lambda - shape parameter
* @returns {number} evaluated MGF
*
* @example
* var y = mgf( 0.1, 2.0, 3.0 );
* // returns ~1.2405
*
* @example
* var y = mgf( -1.0, 0.5, 2.0 );
* // returns ~0.6237
*
* @example
* var y = mgf( NaN, 0.5, 2.0 );
* // returns NaN
*
* @example
* var y = mgf( 0.1, NaN, 2.0 );
* // returns NaN
*
* @example
* var y = mgf( 0.1, 0.5, NaN );
* // returns NaN
*
* @example
* var y = mgf( 0.1, -1.0, 2.0 );
* // returns NaN
*
* @example
* var y = mgf( 0.1, 0.5, -2.0 );
* // returns NaN
*
* @example
* var y = mgf( 1.0, 2.0, 3.0 );
* // returns NaN
*/
function mgf( t, mu, lambda ) {
	var mu2Lambda;
	var lambdaMu;
	if (
		isnan( t ) ||
		isnan( mu ) ||
		isnan( lambda ) ||
		mu <= 0.0 ||
		lambda <= 0.0 ||
		t > lambda / ( 2.0 * mu * mu )
	) {
		return NaN;
	}
	lambdaMu = lambda / mu;
	mu2Lambda = 2.0 * mu * mu / lambda;
	return exp( lambdaMu * ( 1.0 - sqrt( 1.0 - ( mu2Lambda * t ) ) ) );
}


// EXPORTS //

export default mgf;
