'use strict';

/**
* Evaluate the moment-generating function (MGF) for a Wald distribution.
*
* @module @stdlib/stats-base-dists-wald-mgf
*
* @example
* import mgf from '@stdlib/stats-base-dists-wald-mgf';
*
* var y = mgf( 0.1, 2.0, 3.0 );
* // returns ~1.2405
*
* y = mgf( -1.0, 0.5, 2.0 );
* // returns ~0.6237
*
* var mymgf = mgf.factory( 2.0, 3.0 );
*
* y = mymgf( 0.1 );
* // returns ~1.2405
*
* y = mymgf( 0.2 );
* // returns ~1.6085
*/

// MODULES //

import setReadOnly from '@stdlib/utils-define-nonenumerable-read-only-property';
import main from './main.js';
import factory from './factory.js';


// MAIN //

setReadOnly( main, 'factory', factory );


// EXPORTS //

export default main;
